'use strict';
const EX=window.EXAMS;
function examState(y){if(!state.exams||typeof state.exams!=='object')state.exams={};if(!state.exams[y])state.exams[y]={listening:{},grammar:{},writing:'',plan:'',self:{},submitted:false,timer:null};return state.exams[y];}
function onlineExamLibrary(){return head('Die Originaltests. Direkt hier ausfüllen.','Bearbeite alle drei Prüfungsteile online: Hörverstehen, Use of English und Sprachmittlung. Die Aufgabenformate und Inhalte entsprechen den bereitgestellten Tests.','Originaltests 2021–2025')+`<div class="panel tint"><h2>Ein Test, ein gespeicherter Antwortbogen.</h2><p>Wähle einen Jahrgang. Deine Antworten und Schreibtexte bleiben auf diesem Gerät erhalten. Nach der Abgabe erhältst du die Grammatik-Auswertung und die Lösungshinweise für deine Selbstkontrolle.</p><p class="meta">60 Minuten · 15 BE Hörverstehen · 15 BE Use of English · 20 BE Sprachmittlung. Ohne Anmeldung.</p><p class="meta">Hörverstehen gibt es ausschließlich hier in den Originaltests. Im vorbereitenden Training werden diese Hörtexte nicht vorweggenommen.</p></div>${D.years.filter(y=>y.year>=2021).map(y=>{const s=examState(y.year),n=examFilled(y.year);return `<article class="exam-library-row"><div class="exam-year">${y.year}</div><div><h2>${E(y.listening)}</h2><p class="meta">Sprachmittlung: ${E(y.writing)} · ${y.words} Wörter</p><span class="pill">${s.submitted?'Abgegeben · Auswertung verfügbar':n?`${n} Antwortfelder bearbeitet`:'Noch nicht begonnen'}</span></div><a class="button ${n?'secondary':''}" href="#exam/${y.year}">${s.submitted?'Auswertung öffnen':n?'Test fortsetzen':'Test online starten'}</a></article>`;}).join('')}<details style="margin-top:32px"><summary>Original-PDFs, Hördateien und Zusatzmaterial</summary>${D.years.filter(y=>y.year>=2021).map(materialRow).join('')}</details><details><summary>Älteres Zusatzmaterial: 2018 und 2019</summary><p class="meta">Freiwilliges PDF-Archiv. Diese Jahrgänge sind nicht Teil der Online-Generalproben. Für 2018 fehlen Hördatei und Lösungen; für 2020 liegen keine Materialien vor.</p>${D.years.filter(y=>y.year<2021).map(materialRow).join('')}</details><p class="source-note">Die bereitgestellten Originale bleiben unverändert abrufbar. Im Onlineformular sind Tabellen und Zeilenumbrüche für kleine Bildschirme angepasst. Historische Angaben gelten für den jeweiligen Ausgangstext. Die Textproduktionen der Sommer-Tests sind separates Zusatztraining.</p>`;}
function examFilled(y){const s=examState(y);return Object.values(s.listening).filter(v=>Array.isArray(v)?v.length:String(v).trim()).length+Object.values(s.grammar).filter(v=>String(v).trim()).length+(s.writing.trim()?1:0);}
function onlineTest(id){const y=EX[id]?Number(id):2025,e=EX[y],s=examState(y),meta=year(y);const disabled=s.submitted?'disabled':'';return `<a class="back" href="#exams">← Alle Originaltests</a>${head('Originaltest '+y,'Alle Antworten werden auf diesem Gerät gespeichert. Du kannst jederzeit unterbrechen und später fortsetzen.','Online ausfüllbar · Klasse 10')}<div class="exam-toolbar"><div class="exam-jump" aria-label="Prüfungsteile">${button('I · Listening','exam-jump:listening','secondary')}${button('II · Use of English','exam-jump:grammar','secondary')}${button('III · Sprachmittlung','exam-jump:writing','secondary')}</div><span id="exam-saved" class="meta" role="status">${storageOK?'Lokal gespeichert':'Speichern nicht verfügbar'}</span></div><div class="panel exam-info"><div><strong>Deine Generalprobe</strong><p class="meta">60 Minuten insgesamt. Optionaler Timer, keine automatische Abgabe.</p>${pdfLink(meta.task,'Original-PDF zum Vergleichen')}</div><div class="timer"><output data-exam-timer="${y}" aria-label="Verbleibende Testzeit">${examTimeLabel(y)}</output>${button(s.timer?.running?'Pausieren':'Timer starten / fortsetzen','exam-timer:'+y,'secondary',disabled)}${button('Zurücksetzen','exam-reset-timer:'+y,'text',disabled)}</div></div>${s.submitted?examResults(y):''}
 <details class="exam-part" id="exam-listening" open><summary><span>I · Listening Comprehension</span><span class="pill">15 BE</span></summary><h2>${E(meta.listening)}</h2>${y===2024?'<p lang="en">President Biden has decided to designate (i.e. officially declare) two places to be national monuments.</p>':''}${y===2022?'<p lang="en">You will hear a podcast about Jill Heinerth, a cave diver.</p>':''}<p class="meta">${y>=2023?'The tasks are not necessarily in the right order. ':''}Der Track enthält den Hörtext zweimal sowie Anweisungen und Pausen. Für die Generalprobe einmal durchlaufen lassen.</p>${audioBlock(meta)}${e.listening.map(group=>`<section class="exam-question"><h3 lang="en">${E(group.title)}</h3>${group.image?`<img class="exam-figure" src="${group.image}" alt="${E(group.alt)}" loading="lazy"><p class="meta">Originalabbildungen, Reihenfolge A · B · C von links nach rechts.</p>`:''}${group.items.map(item=>examListeningField(y,item)).join('')}</section>`).join('')}</details>
 <details class="exam-part" id="exam-grammar"><summary><span>II · Use of English</span><span class="pill">15 BE</span></summary>${e.passages.map(p=>`<section class="exam-question"><h2>${E(p.title)}</h2><p class="meta">${p.kind==='correction'?'Read the text and decide whether the underlined parts are correct or not. If they are right, tick “Schon richtig”. If not, write your correction.':p.kind==='gap'?'Use the correct forms of the words in brackets to complete the sentences.':'Complete the text using one word or expression from each selection.'}</p><div class="exam-passage" lang="en">${examPassage(y,p)}</div>${p.kind==='correction'?`<div class="correction-grid">${e.grammar.filter(g=>g.type==='correction'&&Number(g.id)>p.offset).map(g=>examCorrection(y,g)).join('')}</div>`:''}</section>`).join('')}${s.submitted?`<details><summary>Alle Grammatikerklärungen ansehen</summary>${e.grammar.map(g=>examGrammarFeedback(y,g)).join('')}</details>`:''}</details>
 <details class="exam-part" id="exam-writing"><summary><span>III · Sprachmittlung</span><span class="pill">20 BE</span></summary><div class="writing-layout"><section><h2>Originalauftrag & Ausgangstext</h2><div class="exam-source">${E(e.writingSource)}</div>${pdfLink(meta.task,'Originalseite öffnen',meta.page)}</section><section><h2>Deine Antwort</h2><label for="exam-plan">Planung und Stichpunkte (optional)</label><textarea id="exam-plan" class="exam-plan" data-exam="${y}" data-exam-field="plan" ${disabled}>${E(s.plan)}</textarea><div class="row"><label for="exam-writing-text"><strong>Dein englischer Text</strong></label><span class="pill" id="exam-word-count">${wordCount(s.writing)} Wörter</span></div><p class="meta">Ziel: etwa ${meta.words} Wörter laut Originalauftrag.</p><textarea id="exam-writing-text" data-exam="${y}" data-exam-field="writing" lang="en" spellcheck="false" ${disabled}>${E(s.writing)}</textarea><p class="meta">In der Generalprobe ist die Rechtschreibhilfe dieses Feldes ausgeschaltet. Browser-Erweiterungen können davon abweichen.</p>${s.submitted?`<details open><summary>Offizieller Erwartungshorizont</summary><div class="exam-source">${E(e.writingKey)}</div></details><h3>Deine Selbsteinschätzung</h3><p class="meta">Inhalt: maximal 4 BE; Sprache: maximal 6 BE. Die Summe wird verdoppelt. Freie Texte werden nicht automatisch bewertet.</p>${examSelfSelect(y,'content',4,'Inhalt & Strategie',.5)}${examSelfSelect(y,'language',6,'Sprache',.5)}${pdfLink(meta.solution,'Detailliertes Bewertungsraster öffnen',4)}`:''}</section></div></details>
 <section class="panel exam-finish"><h2>${s.submitted?'Deine Arbeit ist gespeichert.':'Bereit für die Auswertung?'}</h2><p class="meta">${s.submitted?'Lade deinen vollständigen Antwortbogen herunter oder bearbeite den Test weiter.':'Erst abgeben, dann vergleichen. Die Grammatik und Ankreuzaufgaben werden automatisch geprüft. Freie Hörantworten und deinen Schreibtext bewertest du anhand der Lösungshinweise selbst.'}</p><div class="actions">${s.submitted?button('Antworten weiter bearbeiten','exam-edit:'+y):button('Test abgeben & auswerten','exam-submit:'+y)}${button('Antwortbogen herunterladen','exam-export:'+y,'secondary')}<a href="#exams">Speichern & später weiter</a></div></section>`;}
function examListeningField(y,item){const s=examState(y),value=s.listening[item.id],disabled=s.submitted?'disabled':'';const id='el-'+item.id;let content;if(item.type==='choice'){const selected=Array.isArray(value)?value:[];content=`<fieldset class="exam-choice"><legend lang="en">${E(item.label)} <span class="meta">(${item.points===1?'1 Antwort':item.points+' Antworten'})</span></legend>${item.options.map((o,i)=>`<label class="choice"><input type="${item.points===1?'radio':'checkbox'}" name="${id}" data-exam="${y}" data-exam-choice="${item.id}" value="${i}" ${selected.includes(i)?'checked':''} ${disabled}><span lang="en">${E(o)}</span></label>`).join('')}</fieldset>`;if(s.submitted){const score=examChoiceScore(item,selected);content+=`<div class="feedback ${score===item.points?'correct':''}"><strong>${score} / ${item.points} BE automatisch geprüft</strong><p>Richtig: ${item.correct.map(i=>E(item.options[i])).join(' · ')}</p></div>`;}}else{content=`<div class="field"><label for="${id}" lang="en">${E(item.label)}</label><input id="${id}" type="text" data-exam="${y}" data-exam-listen="${item.id}" value="${E(value||'')}" autocomplete="off" spellcheck="false" ${disabled}></div>`;if(s.submitted)content+=`<div class="feedback"><p><strong>Lösungshinweis:</strong> ${E(item.key)}</p><p class="meta">Vergleiche die Bedeutung. Sinnentsprechende Varianten zählen; doppelte Antworten bei „two reasons/items“ nicht zweimal werten.</p>${examSelfSelect(y,'l:'+item.id,1,'Deine Punkte für Aufgabe '+item.id,y===2022?1:.5)}</div>`;}return`<div class="exam-item">${content}</div>`;}
function examChoiceScore(item,selected=[]){if(selected.length>item.points)return 0;return [...new Set(selected)].filter(i=>item.correct.includes(i)).length;}
function examPassage(y,p){const s=examState(y);return E(p.text).replace(/\{\{(\d+)\|([^}]+)\}\}/g,(_,n,hint)=>{const g=EX[y].grammar.find(g=>g.id===n);if(p.kind==='correction')return`<strong class="original-underline">${hint}<sup>${n}</sup></strong>`;const value=s.grammar[n]||'',disabled=s.submitted?'disabled':'';return`<label class="inline-gap"><span>${n}${hint==='choice'?'':` · (${hint})`}</span>${g.type==='choice'?`<select data-exam="${y}" data-exam-grammar="${n}" aria-label="Lücke ${n}" ${disabled}><option value="">Bitte wählen</option>${g.options.map(v=>`<option value="${E(v)}" ${value===v?'selected':''}>${E(v)}</option>`).join('')}</select>`:`<input type="text" data-exam="${y}" data-exam-grammar="${n}" value="${E(value)}" aria-label="Lücke ${n}: ${hint}" autocomplete="off" autocapitalize="off" spellcheck="false" ${disabled}>`}</label>`;});}
function examCorrection(y,g){const s=examState(y),value=s.grammar[g.id]||'',tick=value==='✓';return `<div class="correction-row"><div><label for="eg-${g.id}"><strong>${g.id}. <span lang="en">${E(g.original)}</span></strong></label><label class="correct-checkbox"><input type="checkbox" data-exam="${y}" data-exam-correct="${g.id}" ${tick?'checked':''} ${s.submitted?'disabled':''}> Schon richtig</label></div><input type="text" id="eg-${g.id}" data-exam="${y}" data-exam-grammar="${g.id}" value="${tick?'':E(value)}" placeholder="Korrektur" autocomplete="off" autocapitalize="off" spellcheck="false" ${s.submitted||tick?'disabled':''}></div>`;}
function examGrammarCorrect(g,answer){return g.answers.some(a=>normalize(a,g.caseSensitive)===normalize(answer||'',g.caseSensitive));}
function examGrammarFeedback(y,g){const s=examState(y),correct=examGrammarCorrect(g,s.grammar[g.id]);return`<div class="feedback ${correct?'correct':''}"><h3>${g.id}. ${correct?'Richtig':'Noch einmal ansehen'}</h3><p>Deine Antwort: <strong>${E(s.grammar[g.id]||'nicht beantwortet')}</strong><br>Lösung: ${g.answers[0]==='✓'?'Die ursprüngliche Form ist bereits richtig.':g.answers.map(E).join(' / ')}</p><p>${E(g.explanation)}</p><a href="#grammar/${g.topic}">Regel nachschlagen</a></div>`;}
function examSelfSelect(y,key,max,label,step){const s=examState(y);let values=[];for(let i=0;i<=max;i+=step)values.push(i);return `<div class="self-score"><label for="es-${key}">${E(label)}</label><select id="es-${key}" data-exam="${y}" data-exam-self="${key}"><option value="">Noch nicht eingeschätzt</option>${values.map(n=>`<option value="${n}" ${s.self[key]!==undefined&&s.self[key]!==''&&Number(s.self[key])===n?'selected':''}>${n.toLocaleString('de-DE')} / ${max} BE</option>`).join('')}</select></div>`;}
function examScore(y){const s=examState(y),e=EX[y];let grammar=e.grammar.filter(g=>examGrammarCorrect(g,s.grammar[g.id])).length;const items=e.listening.flatMap(g=>g.items);const auto=items.filter(i=>i.type==='choice').reduce((sum,i)=>sum+examChoiceScore(i,s.listening[i.id]||[]),0);const free=items.filter(i=>i.type==='text');const ungraded=free.filter(i=>s.self['l:'+i.id]===undefined||s.self['l:'+i.id]==='').length;const manual=free.reduce((sum,i)=>sum+Number(s.self['l:'+i.id]||0),0);const writing= ['content','language'].some(k=>s.self[k]===undefined||s.self[k]==='')?null:(Number(s.self.content)+Number(s.self.language))*2;return{grammar,listening:auto+manual,listeningAuto:auto,ungraded,writing,total:ungraded||writing===null?null:grammar+auto+manual+writing};}
function examResults(y){const r=examScore(y);return`<section class="panel tint" id="exam-results" tabindex="-1"><h2>Deine Auswertung</h2><div id="exam-score-summary" aria-live="polite">${examSummary(y)}</div><p class="meta">Use of English und Ankreuzaufgaben sind automatisch geprüft. Für freie Antworten vergibst du die Punkte selbst; das Gesamtergebnis ist deshalb eine Selbsteinschätzung, keine offizielle Note.</p><div class="actions">${button('Lösungen beim Hörverstehen','exam-jump:listening','secondary')}${button('Grammatikerklärungen','exam-jump:grammar','secondary')}${button('Schreibtext prüfen','exam-jump:writing','secondary')}</div></section>`;}
function examSummary(y){const r=examScore(y);return`<ul><li><strong>Use of English: ${r.grammar} / 15 BE</strong> · automatisch geprüft</li><li>Hörverstehen: ${r.ungraded?`${r.listeningAuto} BE aus Ankreuzaufgaben; ${r.ungraded} freie Antworten noch selbst einschätzen`:`${r.listening.toLocaleString('de-DE')} / 15 BE einschließlich Selbsteinschätzung`}</li><li>Sprachmittlung: ${r.writing===null?'noch selbst einschätzen':r.writing+' / 20 BE selbst eingeschätzt'}</li></ul>${r.total===null?'<p>Die Gesamtsumme erscheint, wenn du alle freien Antworten eingeschätzt hast.</p>':`<p class="result-number">${r.total.toLocaleString('de-DE')} / 50 BE</p>`}`;}
function examRemaining(y){const t=examState(y).timer;return !t?3600:t.running?Math.max(0,Math.ceil((t.deadline-Date.now())/1000)):t.remaining;}
function examTimeLabel(y){const s=examRemaining(y);return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');}
function examSave(){const ok=save();const status=$('#exam-saved');if(status)status.textContent=ok?'Lokal gespeichert':'Speichern nicht verfügbar. Bitte Antwortbogen herunterladen.';}
function examExport(y){const s=examState(y),e=EX[y];let lines=[`English Lab · Originaltest ${y}`,`Stand: ${new Date().toLocaleString('de-DE')}`,s.submitted?'Abgegeben zur Selbstkontrolle':'Entwurf','\nI · LISTENING'];for(const g of e.listening){lines.push('\n'+g.title);for(const i of g.items){const val=s.listening[i.id];lines.push(i.label, i.type==='choice'?(val||[]).map(n=>i.options[n]).join(' / ')||'—':val||'—');}}lines.push('\nII · USE OF ENGLISH');for(const g of e.grammar)lines.push(`${g.id}. ${g.original?g.original+' → ':''}${s.grammar[g.id]||'—'}`);lines.push('\nIII · SPRACHMITTLUNG','Planung:',s.plan,'Text:',s.writing,`Wörter: ${wordCount(s.writing)}`);if(s.submitted){const r=examScore(y);lines.push('\nAUSWERTUNG',`Grammatik automatisch: ${r.grammar}/15`,`Hörverstehen: ${r.listening}/15 (${r.ungraded} Antworten noch ohne Selbsteinschätzung)`,`Schreiben: ${r.writing??'offen'}/20 (Selbsteinschätzung)`,`Gesamt: ${r.total??'noch offen'}/50`);}download(`English-Lab-Originaltest-${y}-Antworten.txt`,lines.join('\n'));}
document.addEventListener('input',event=>{const el=event.target,y=el.dataset.exam;if(!y||!EX[y])return;const s=examState(y);if(s.submitted)return;if(el.dataset.examListen)s.listening[el.dataset.examListen]=el.value;if(el.dataset.examGrammar)s.grammar[el.dataset.examGrammar]=el.value;if(el.dataset.examField){s[el.dataset.examField]=el.value;if(el.dataset.examField==='writing')$('#exam-word-count').textContent=wordCount(el.value)+' Wörter';}examSave();});
document.addEventListener('change',event=>{const el=event.target,y=el.dataset.exam;if(!y||!EX[y])return;const s=examState(y);if(el.dataset.examSelf){const key=el.dataset.examSelf,max=key==='content'?4:key==='language'?6:1;const value=el.value;const step=key.startsWith('l:')&&Number(y)===2022?1:.5;if(value!==''&&(!Number.isFinite(Number(value))||Number(value)<0||Number(value)>max||Number(value)%step!==0))return;s.self[key]=value;examSave();if($('#exam-score-summary'))$('#exam-score-summary').innerHTML=examSummary(y);return;}if(s.submitted)return;if(el.dataset.examChoice){const key=el.dataset.examChoice;const item=EX[y].listening.flatMap(g=>g.items).find(i=>i.id===key);const checked=[...document.querySelectorAll(`[data-exam-choice="${key}"]:checked`)].map(x=>Number(x.value));if(checked.length>item.points){el.checked=false;notify(`Bitte höchstens ${item.points} Antworten auswählen.`);return;}s.listening[key]=checked;}if(el.dataset.examCorrect){const key=el.dataset.examCorrect;s.grammar[key]=el.checked?'✓':'';const input=$(`#eg-${key}`);input.value='';input.disabled=el.checked;if(!el.checked)input.focus();}if(el.dataset.examGrammar)s.grammar[el.dataset.examGrammar]=el.value;examSave();});
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b)return;const [action,v]=b.dataset.action.split(':');if(action==='exam-jump'){const el=$('#exam-'+v);if(el){el.open=true;el.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}return;}if(!action.startsWith('exam-')||!EX[v])return;const y=Number(v),s=examState(y);if(action==='exam-submit'){const total=EX[y].listening.flatMap(g=>g.items).length+16;const filled=examFilled(y);if(filled<total&&!confirm(`Es sind noch Antwortfelder leer (${filled} von ${total} bearbeitet). Trotzdem abgeben und Lösungen anzeigen?`))return;s.submitted=true;s.submittedAt=new Date().toISOString();if(s.timer?.running)s.timer={running:false,remaining:examRemaining(y)};examSave();render(false);$('#exam-results').focus();$('#exam-results').scrollIntoView({block:'start'});return;}if(action==='exam-edit'){s.submitted=false;s.self={};examSave();render(false);notify('Du kannst die Antworten wieder bearbeiten. Die Selbsteinschätzung wird bei der nächsten Abgabe neu vorgenommen.');return;}if(action==='exam-export'){examExport(y);return;}if(action==='exam-timer'){const left=examRemaining(y);s.timer=s.timer?.running?{running:false,remaining:left}:{running:true,deadline:Date.now()+(left||3600)*1000};examSave();b.textContent=s.timer.running?'Pausieren':'Timer starten / fortsetzen';return;}if(action==='exam-reset-timer'&&confirm('Timer dieses Tests auf 60 Minuten zurücksetzen?')){s.timer=null;examSave();const o=$(`[data-exam-timer="${y}"]`);if(o)o.textContent=examTimeLabel(y);const bt=$(`[data-action="exam-timer:${y}"]`);if(bt)bt.textContent='Timer starten / fortsetzen';}});
setInterval(()=>{if(typeof state==='undefined'||!state.exams)return;for(const [y,s] of Object.entries(state.exams)){if(s.timer?.running&&examRemaining(y)===0){s.timer={running:false,remaining:0};save();notify(`Originaltest ${y}: Die 60 Minuten sind um. Du kannst jetzt abgeben.`);}const o=document.querySelector(`[data-exam-timer="${y}"]`);if(o)o.textContent=examTimeLabel(y);}},1000);
